INSERT INTO public.ai_knowledge (topic, content, category) VALUES
('sum', E'SUM - Menjumlahkan Angka. =SUM(A1:A100). =SUM(A1:A5,C1:C5). SUM mengabaikan teks & sel kosong. SUMPRODUCT untuk perkalian lalu jumlah.', 'excel'),
('average', E'AVERAGE - Rata-rata. =AVERAGE(B1:B30). =AVERAGEIF(A1:A10,">5"). =AVERAGEIFS(B1:B10,A1:A10,"Jan",C1:C10,">100"). Rata-rata tertimbang: =SUMPRODUCT(A:A,B:B)/SUM(B:B)', 'excel'),
('count', E'COUNT - Menghitung. =COUNT(angka). =COUNTA(tidak kosong). =COUNTBLANK(kosong). =COUNTIF(range,kondisi). =COUNTIFS(range1,kondisi1,range2,kondisi2). Wildcard: * = any char, ? = single char.', 'excel'),
('max_min', E'MAX, MIN, LARGE, SMALL. =MAX(A1:A10). =MIN(A1:A10). =LARGE(range,2) terbesar ke-2. =SMALL(range,3) terkecil ke-3. =MAXIFS(B:B,A:A,"Jan"). =MINIFS(B:B,A:A,"Aktif").', 'excel'),
('round', E'ROUND, ROUNDUP, ROUNDDOWN, CEILING, FLOOR, MROUND, INT, TRUNC. =ROUND(3.14159,2)=3.14. =ROUNDUP ke atas. =CEILING(4.1,1) kelipatan terdekat atas. =MROUND(4.3,5)=5.', 'excel'),
('sumproduct', E'SUMPRODUCT: Kalikan Lalu Jumlahkan. =SUMPRODUCT(A1:A5,B1:B5). Conditional: =SUMPRODUCT((A:A="Jan")*(B:B>100)*(C:C)). * = AND, + = OR. Unary -- konversi TRUE/FALSE ke 1/0.', 'excel'),
('abs_mod', E'ABS(-5)=5. MOD(10,3)=1 sisa bagi. QUOTIENT(10,3)=3 hasil bagi. MOD untuk alternating: =IF(MOD(ROW(),2)=0,"Even","Odd"). ABS untuk jarak absolut.', 'excel'),
('power_math', E'POWER(2,10)=1024. SQRT(144)=12. PI()=3.14159. EXP(1)=2.71828. LN(natural log). LOG10, LOG(base). FACT(5)=120. RANDBETWEEN(1,100). RAND() 0-1. VOLATILE.', 'excel'),
('sequence_func', E'SEQUENCE & RANDARRAY (Excel 365/Sheets). =SEQUENCE(5) 1-5. =SEQUENCE(3,4) 3x4 matrix. =SEQUENCE(5,1,10,2) mulai 10 step 2. =RANDARRAY(3,4,1,100,TRUE) random integer.', 'excel'),
('if', E'IF - Conditional Logic. =IF(kondisi,benar,salah). Contoh: =IF(A1>60,"Lulus","Gagal"). Nesting max 64 level. Tips: Gunakan IFS untuk multi-kondisi lebih rapi. SWITCH untuk pencocokan nilai tepat.', 'excel'),
('ifs', E'IFS - Multiple Conditions Tanpa Nesting. =IFS(A1>=90,"A",A1>=80,"B",A1>=70,"C",TRUE,"D"). TRUE sebagai fallback terakhir. Lebih rapi dari IF bersarang. Excel 2019+/Sheets.', 'excel'),
('switch_func', E'SWITCH - Cocokkan Nilai Tepat. =SWITCH(A1,"Jan","Januari","Feb","Februari","Mar","Maret","?"). Default di akhir tanpa value. Lebih rapi dari IF untuk multi-case mapping.', 'excel'),
('and_or_not', E'AND(cond1,cond2) semua harus TRUE. OR(cond1,cond2) minimal satu TRUE. NOT(cond) negasi. Contoh: =IF(AND(A1>0,A1<100),"Valid","Invalid"). SUMPRODUCT: * = AND, + = OR.', 'excel'),
('iferror', E'IFERROR(formula,pesan_error). IFNA(formula,pesan) khusus #N/A. Error types: #DIV/0!, #N/A, #NAME?, #NULL!, #NUM!, #REF!, #VALUE!. Gunakan dengan VLOOKUP untuk graceful fallback.', 'excel'),
('choose', E'CHOOSE(n,val1,val2,...). =CHOOSE(A1,"Januari","Februari","Maret"). 1=Januari, 2=Feb, dst. Max 254 pilihan. CHOOSE(MONTH(A1),"Q1","Q1","Q1","Q2","Q2","Q2","Q3","Q3","Q3","Q4","Q4","Q4") untuk quarter.', 'excel'),
('let_lambda', E'LET(var1,expr1,var2,expr2,result). Max 126 variabel. Membaca formula kompleks. LAMBDA(x,x^2) buat fungsi custom. Named Range: =LAMBDA(x,x*2) lalu panggil =DoubleRange(A1). Excel 365.', 'excel'),
('vlookup', E'VLOOKUP(cari,range,kolom_ke,[FALSE]). FALSE = exact match (PALING SERING). TRUE = approximate (range harus ASC). HANYA ke KANAN. Kolom dihitung dari range. Tips: Untuk ke kiri pakai INDEX-MATCH.', 'excel'),
('index_match', E'INDEX(ambil_range,MATCH(cari,cari_range,0)). 0=exact, 1=less than, -1=greater than. Bisa ke KIRI. Multi-kriteria: =INDEX(C:C,MATCH(1,(A:A=A1)*(B:B=B1),0)) Ctrl+Shift+Enter. Formula favorit profesional.', 'excel'),
('xlookup', E'XLOOKUP(cari,range_cari,range_ambil,[default],[match],[search]). Match: 0=exact, -1=smaller, 1=larger, 2=wildcard. Search: 1=first, -1=last. Menggantikan VLOOKUP/HLOOKUP/INDEX-MATCH. Excel 365.', 'excel'),
('hlookup', E'HLOOKUP: Horizontal lookup. =HLOOKUP(cari,range_baris,baris_ke,FALSE). Jarang dipakai karena data biasanya vertical. XLOOKUP atau TRANSPOSE lebih baik.', 'excel'),
('indirect', E'INDIRECT(ref_teks). =INDIRECT("A"&B1). Dynamic named range: =INDIRECT("A1:A"&COUNTA(A:A)). VOLATILE (lambat). Hati-hati delete row corrupt reference. INDEX lebih cepat.', 'excel'),
('left_right_mid', E'LEFT(A1,5) 5 dari kiri. RIGHT(A1,4) 4 dari kanan. MID(A1,3,6) dari posisi 3 ambil 6. LEN panjang. TRIM hapus spasi. CLEAN hapus non-printable. VALUE konversi ke angka.', 'excel'),
('upper_lower', E'UPPER=SEMUA BESAR. LOWER=semua kecil. PROPER=Setiap Kata Huruf Besar. SUBSTITUTE(A1,"old","new") ganti semua. SUBSTITUTE(...,1) kejadian pertama. EXACT(A1,A2) case-sensitive.', 'excel'),
('concatenate', E'A1&" "&B1 cara singkat. CONCATENATE(A1," ",B1). TEXTJOIN(", ",TRUE,A1:A10) join dengan delimiter. TEXT(A1,"DD-MMM-YYYY") format. TEXT(A1,"#,##0") angka. TEXT(A1,"0.00%") persen.', 'excel'),
('find_search', E'FIND("@",A1) case-sensitive. SEARCH("@",A1) case-insensitive. Return posisi 1-based. ISNUMBER(FIND("@",A1)) cek keberadaan. Combine dengan LEFT/MID/RIGHT untuk ekstrak.', 'excel'),
('is_functions', E'ISNUMBER(angka)=TRUE. ISTEXT(teks)=TRUE. ISBLANK(kosong)=TRUE. ISERROR(semua error). ISERR(kecuali #N/A). ISNA(hanya #N/A). ISEVEN(4)=TRUE. ISODD(3)=TRUE. Berguna di IF dan SUMPRODUCT.', 'excel'),
('clean_func', E'CLEAN=hapus non-printable. CHAR(65)="A" ASCII ke char. CODE("A")=65 char ke ASCII. REPT("=",20) ulang teks. T(A1)=teks atau "". N(A1)=angka atau 0.', 'excel'),
('today_now', E'TODAY() tanggal hari ini. NOW() tanggal+waktu. TODAY()+7 7 hari lagi. VOLATILE: berubah setiap recalc. Ctrl+; timestamp tetap tanggal. Ctrl+Shift+; timestamp waktu.', 'excel'),
('date_parts', E'YEAR/MONTH/DAY(A1) ambil komponen. DATE(2024,12,25) buat tanggal. DATEVALUE("25/12/2024") teks ke tanggal. DATEDIF(A1,B1,"D") hari. "M" bulan. "Y" tahun. "YM" bulan tanpa tahun.', 'excel'),
('endmonth', E'EOMONTH(A1,0) akhir bulan. WORKDAY(A1,10) +10 hari kerja. NETWORKDAYS(A1,B1) hitung hari kerja. WEEKDAY(A1) 1=Min,7=Sab. WEEKNUM(A1) nomor minggu. Exclude holiday: WORKDAY(A1,10,range_holiday).', 'excel'),
('edate', E'EDATE(A1,3) 3 bulan dari A1. YEARFRAC(A1,B1) selisih tahun desimal. DAYS360(A1,B1) 30/360 bond market. DAYS(A1,B1) hari actual. Berguna untuk maturity dates dan interest calculations.', 'excel'),
('sumif', E'SUMIF(range_kondisi,kondisi,range_jumlah). 1 kondisi. SUMIFS(range_jumlah,rk1,k1,rk2,k2,...) multi-kondisi. SUMIFS: range pertama = penjumlahan. Wildcard: "*text*" untuk parsial.', 'excel'),
('countif', E'COUNTIF(range,kondisi). COUNTIFS untuk AND multi-kondisi. Wildcard: * any chars, ? single char. COUNTIF(A:A,"<>") hitung tidak kosong. OR: =COUNTIF(..)+COUNTIF(..)-COUNTIFS(..).', 'excel'),
('averageif', E'AVERAGEIF(range_kondisi,kondisi,range_rata2). AVERAGEIFS untuk multi. Ingat: range rata-rata di POSISI PERTAMA di AVERAGEIFS (berbeda SUMIFS).', 'excel'),
('maxif_minif', E'MAXIFS(range,rk1,k1,...). MINIFS sama. Excel 2019+/Sheets. Alternatif lama: =MAX(IF(A:A="Jan",B:B)) Ctrl+Shift+Enter.', 'excel'),
('conditional_format', E'Conditional Formatting: Cell Rules, Top/Bottom, Data Bars, Color Scales (heatmap), Icon Sets. Custom Formula: =MOD(ROW(),2)=0 zebra rows. Highlight duplikat: =COUNTIF($A:$A,$A1)>1. Priority dari atas ke bawah.', 'excel'),
('gsheet_query', E'QUERY(data,query_string,header). SQL-like: SELECT, WHERE, GROUP BY, ORDER BY, HAVING, PIVOT, LABEL, FORMAT, LIMIT. Paling powerful function di Google Sheets! String pakai single quote dalam SQL. Contoh: =QUERY(A1:D100,SELECT A,SUM(C) WHERE B=Active GROUP BY A,1)', 'gsheet'),
('gsheet_filter', E'FILTER(data,kondisi). * = AND, + = OR. =FILTER(A:C,(A:A="Jan")+(A:A="Feb")). Wrap IFERROR jika tidak ada hasil. Lebih baik dari AutoFilter, otomatis update.', 'gsheet'),
('gsheet_sort', E'SORT(data,kolom,TRUE/FALSE). TRUE=ASC, FALSE=DESC. Multi-level: =SORT(range,3,FALSE,1,TRUE). Combine: =SORT(FILTER(...),2,TRUE). Dynamic dari Data > Sort.', 'gsheet'),
('gsheet_unique', E'UNIQUE(range). =SORT(UNIQUE(A1:A100)) unik terurut. =COUNTA(UNIQUE(A1:A100)) jumlah unik. Multi-kolom: =UNIQUE(A1:C100). FILTER+UNIQUE untuk conditional.', 'gsheet'),
('gsheet_arrayformula', E'ARRAYFORMULA(IF(range,expr,"")). Terapkan formula ke seluruh kolom. Powerful tapi LAMBAT. Query/Filter sering lebih cepat. Jangan dengan sel tunggal. Bisa #REF! jika ada data di bawah.', 'gsheet'),
('gsheet_sparkline', E'SPARKLINE(data,[options]). =SPARKLINE(A1:A10) line. =SPARKLINE(range,{"charttype","bar"}). Types: line, bar, column, winloss, pie. Custom: color, linewidth. Dashboard mini.', 'gsheet'),
('gsheet_import', E'IMPORTHTML(URL,"table",n) import tabel web. IMPORTXML(URL,xpath) XPath query. IMPORTDATA(URL) CSV/TSV. IMPORTRANGE("url","Sheet1!A1:D100") antar spreadsheet. Max 50 per spreadsheet. LAMBAT.', 'gsheet'),
('gsheet_gfinance', E'GOOGLEFINANCE("AAPL") harga saham. "price", "changepct", "marketcap", "volume". =GOOGLEFINANCE("USDIDR") kurs. Historical: =GOOGLEFINANCE("AAPL","price","1/1/2024",TODAY(),"DAILY"). ~20 min delay.', 'gsheet'),
('gsheet_regex', E'REGEXMATCH(teks,pattern) TRUE/FALSE. REGEXEXTRACT ekstrak bagian. REGEXREPLACE ganti. (?i) case-insensitive. \d digit, \w word, \s space. Contoh: =REGEXMATCH(A1,"\\d{3}"). Lebih powerful dari FIND.', 'gsheet'),
('gsheet_hyperlink', E'HYPERLINK(url,text) buat link. mailto: untuk email. tel: untuk telepon. IMAGE(url) tampilkan gambar. IMAGE(url,2) fit container. IMAGE(url,3) actual size. Berguna untuk dashboard interaktif.', 'gsheet'),
('gsheet_array_constrain', E'ARRAY_CONSTRAIN(array,rows,cols). Membatasi output. =ARRAY_CONSTRAINT(QUERY(...),10,3) max 10 baris 3 kolom. Mencegah #REF! dari array terlalu besar. Combine dengan QUERY/FILTER.', 'gsheet'),
('gsheet_makearray', E'MAKEARRAY(rows,cols,lambda). =MAKEARRAY(3,3,LAMBDA(r,c,r*c)). Matrix multiplication: =MMULT(A1:B2,C1:D2). Transpose: =TRANSPOSE(range). FLATTEN: =FLATTEN(range) semua ke 1 kolom.', 'gsheet'),
('math_algebra', E'Algebra Dasar. Linear: ax+b=0 => x=-b/a. Kuadrat: ax^2+bx+c=0 => x=(-b+-sqrt(b^2-4ac))/2a. Discriminant D=b^2-4ac. D>0: 2 akar. D=0: 1 akar. D<0: kompleks. Identitas: (a+b)^2=a^2+2ab+b^2. (a-b)^2=a^2-2ab+b^2. (a+b)(a-b)=a^2-b^2.', 'math'),
('math_percentage', E'Persen & Diskon. X% dari Y=(X/100)*Y. Diskon: Harga*(1-D/100). PPN: Harga*(1+P/100). Profit: ((Jual-Beli)/Beli)*100. Margin: ((Jual-Beli)/Jual)*100. Bunga: FV=PV*(1+r)^n. Diskon bertingkat: H*(1-d1)*(1-d2)*(1-d3). BUKAN H*(1-d1-d2-d3)!', 'math'),
('math_statistics', E'Statistik. Mean=Sum(xi)/n. Median=nilai tengah. Modus=paling sering. Range=Max-Min. Varian=Sum((xi-mean)^2)/n. StdDev=sqrt(Varian). Z-score=(x-mean)/StdDev. CV=(StdDev/Mean)*100%. Kuartil Q1,Q2,Q3. IQR=Q3-Q1.', 'math'),
('math_probability', E'Probabilitas. P(A)=A/Total. P(A or B)=P(A)+P(B)-P(A and B). P(A|B)=P(A and B)/P(B). Bayes: P(A|B)=P(B|A)*P(A)/P(B). Kombinasi C(n,r)=n!/(r!(n-r)!). Permutasi P(n,r)=n!/(n-r)!. Binomial: C(n,k)*p^k*(1-p)^(n-k).', 'math'),
('math_geometri', E'Geometri. Persegi: L=s^2,P=4s. Persegi Panjang: L=p*l,P=2(p+l). Lingkaran: L=pi*r^2,K=2*pi*r. Segitiga: L=alas*tinggi/2. Trapesium: L=(a+b)*h/2. Volume: Kubus s^3, Balok p*l*t, Silinder pi*r^2*h, Kerucut 1/3*pi*r^2*h, Bola 4/3*pi*r^3.', 'math'),
('math_trigonometri', E'Trigonometri. sin=depan/miring. cos=samping/miring. tan=depan/samping. sin^2+cos^2=1. sin(2x)=2sin(x)cos(x). cos(2x)=cos^2x-sin^2x. Radian=Derajat*pi/180. Derajat=Radian*180/pi.', 'math'),
('math_log', E'Logaritma. log_b(x)=y <=> b^y=x. log(a*b)=log(a)+log(b). log(a/b)=log(a)-log(b). log(a^n)=n*log(a). Eksponen: a^0=1. a^(-n)=1/a^n. a^(m/n)=akar ke-n(a^m). e^2.71828...=20.08.', 'math'),
('math_sequences', E'Barisan Aritmetika: an=a1+(n-1)*d. Sn=n/2*(2a1+(n-1)*d). Geometri: an=a1*r^(n-1). Sn=a1*(1-r^n)/(1-r). Sinf=a1/(1-r) jika |r|<1. Fibonacci: an=an-1+an-2.', 'math'),
('math_calculus', E'Kalkulus Dasar. Turunan d/dx[x^n]=nx^(n-1). d/dx[e^x]=e^x. d/dx[ln(x)]=1/x. d/dx[sin(x)]=cos(x). d/dx[cos(x)]=-sin(x). d/dx[tan(x)]=sec^2(x). Product rule: (fg)prima=fprima*g+f*gprima. Chain rule: d/dx[f(g(x))]=fprima(g(x))*gprima(x). Integral: int[x^n]dx=x^(n+1)/(n+1)+C. int[e^x]dx=e^x+C. int[1/x]dx=ln|x|+C.', 'math'),
('math_matrices', E'Matriks. Penjumlahan: A+B (element-wise). Perkalian: (AB)ij = Sum(Aik*Bkj). Determinan 2x2: det(A)=ad-bc. Invers 2x2: A^-1=1/det*[[d,-b],[-c,a]]. Transpose: baris jadi kolom. Identity matrix: diagonal 1. MMULT di Excel/Sheets untuk perkalian matriks.', 'math'),
('math_veter', E'Vektor. |v|=sqrt(x^2+y^2+z^2) panjang. v1+v2 komponen per komponen. v1.v2=x1*x2+y1*y2+y2+z1*z2 dot product. |v1 x v2| cross product magnitude. Sudut: cos(theta)=v1.v2/(|v1|*|v2|).', 'math'),
('coding_python', E'Python: Variable x=10. If/elif/else. For i in range(10). While x>0. List [1,2,3]. Dict key:value. Tuple (1,2). Set {1,2}. Function: def greet(name): return Hi+name. Comprehension: [x**2 for x in range(10)]. Lambda: f=lambda x:x*2. Class: class Dog: def init(self,name): self.name=name. File: with open(f.txt) as f: data=f.read(). Try/Except: try: result=x/y except ZeroDivisionError: print Error.', 'coding'),
('coding_python_adv', E'Python Advanced. Decorator: @timer def func() yang dekorasi fungsi. Generator: def gen(): yield value. Context Manager: with open(f) as f. Regex: import re; re.findall. JSON: json.loads/dumps. CSV: csv.DictReader. Requests: requests.get(url).json(). Collections: Counter, defaultdict, namedtuple. Itertools: chain, product, combinations. Type hints: def func(x: int) -> str.', 'coding'),
('coding_javascript', E'JS ES6+: const/let (no var). Arrow: const f=(a,b)=>a+b. Destructuring: const {name,age}=person; const [a,b]=arr. Spread: [...arr], {...obj}. Map/Filter/Reduce: arr.map(x=>x*2).filter(x=>x>5).reduce((a,b)=>a+b,0). Async/Await: async function f(){const r=await fetch(url);return await r.json()}. Template: `Hello ${name}`. Optional: obj?.value. Nullish: x??"default". DOM: document.querySelector. Events: el.addEventListener. Modules: export/import.', 'coding'),
('coding_sql', E'SQL. SELECT * FROM t WHERE cond ORDER BY col LIMIT 10. INSERT INTO t(col) VALUES(val). UPDATE t SET col=val WHERE cond. DELETE FROM t WHERE cond. JOIN: INNER JOIN, LEFT JOIN, RIGHT JOIN, FULL OUTER JOIN ON a.id=b.a_id. GROUP BY col HAVING COUNT(*)>5. Subquery: WHERE id IN (SELECT...). CTE: WITH cte AS (SELECT...). Window: ROW_NUMBER() OVER(PARTITION BY city ORDER BY age DESC). Index: CREATE INDEX idx ON t(col). Transaction: BEGIN; UPDATE...; COMMIT.', 'coding'),
('coding_git', E'Git. init, add, commit, push, pull, clone. Branch: branch name, checkout -b name, merge name, -d delete. log --oneline --graph. diff, stash, stash pop. Undo: revert (safe, creates undo commit). reset --hard HEAD~1 (destructive). restore file. Remote: remote add origin, fetch, pull origin main, push origin main.', 'coding'),
('coding_react', E'React. Function components: function App(){return <div>}. Hooks: useState, useEffect, useContext, useRef, useMemo, useCallback. Props: function Card({title,children}). Events: onClick, onChange. Conditional: {cond && <Comp/>}. List: {arr.map(x=><Item key={x.id}/>)}. Context: createContext + Provider. Custom Hook: function useFetch(url){useState+useEffect;return data}.', 'coding'),
('coding_node', E'Node.js & Express. const app=express(); app.use(express.json()); app.get("/api/users",async(req,res)=>{...}). app.post/put/delete. Middleware: app.use((req,res,next)=>{...;next()}). Routes: app.use("/api",router). File: fs.readFileSync("f","utf8"). Async: await fs.promises.readFile. Env: process.env.KEY.', 'coding'),
('coding_typescript', E'TypeScript. Types: let x:number=5. let s:string="hi". let a:boolean=true. Interface: interface User{id:number;name:string;email?:string}. Type: type ID=string|number. Generic: function first<T>(arr:T[]):T. Enum: enum Status{Active,Inactive}. Utility: Partial<T>, Required<T>, Pick<T,key>, Omit<T,key>, Record<K,V>. Null: ?? (nullish), !.prop (non-null).', 'coding'),
('coding_algorithms', E'Algorithms & Data Structures. Array O(1) access. LinkedList O(1) insert. Stack LIFO. Queue FIFO. HashMap O(1) lookup. Binary Tree O(log n). Sorting: Bubble/Selection/Insertion O(n^2). Merge/Quick O(n log n). Binary Search O(log n) sorted. Recursion: base case + recursive. Memoization: cache results. Dynamic Programming: optimal substructure.', 'coding'),
('coding_api', E'API & HTTP. Methods: GET, POST, PUT, DELETE, PATCH. Status: 200 OK, 201 Created, 400 Bad Request, 401 Unauthorized, 404 Not Found, 500 Server Error. Headers: Content-Type: application/json, Authorization: Bearer token. Fetch: await fetch(url,{method,headers,body:JSON.stringify(data)}). CORS, REST (resource-based), GraphQL (query language).', 'coding'),
('coding_regex', E'Regular Expressions. \d=digit [0-9]. \w=word. \s=space. .=any char. ^start $end. *0+ *1+ ?0-1. {n} exactly. [abc] class. [^abc] negated. (...) capture. (?:...) non-capture. \b word boundary. Flags: i=case-insensitive, g=global, m=multiline. JS: str.match(/pat/), str.replace(/pat/g,"rep").', 'coding'),
('coding_bash', E'Bash. Variables: NAME="Budi"; echo $NAME. Conditionals: if [ "$1" = "start" ]; then...fi. Loops: for f in *.txt; do...done. While read line; do...done < file. Functions: deploy() {...}; deploy prod. Useful: ls -la | grep, curl, chmod +x, ./script.sh arg1.', 'coding'),
('coding_html_css', E'HTML/CSS. Semantic: header, nav, main, section, article, aside, footer, form. Flexbox: display:flex; justify-content:center; align-items:center; gap:10px. Grid: display:grid; grid-template-columns:repeat(3,1fr); gap:20px. Position: static/relative/absolute/fixed/sticky. Responsive: @media(max-width:768px). box-sizing:border-box. CSS Variables: --primary:#3b82f6; color:var(--primary).', 'coding'),
('writing_email', E'Email Profesional. Subjek: jelas max 8 kata. Salam: "Yth. Bapak/Ibu". Isi: langsung ke poin, paragraf pendek. Penutup: action needed. Follow-up 2-3 hari kerja. CC hati-hati. Reply all hanya perlu. Good: "[Proyek X] Update Deadline 15 Jan".', 'writing'),
('writing_cv', E'CV/Resume. 1. Contact: nama, email, HP, LinkedIn. 2. Summary 2-3 kalimat. 3. Experience: reverse chronological, action verbs (Developed,Led,Increased), quantifiable ("Increased sales 30%"). 4. Education. 5. Skills. Tips: 1-2 halaman. Tailor per lowongan. ATS-friendly keywords.', 'writing'),
('writing_report', E'Laporan Profesional. Cover page, Daftar Isi, Pendahuluan (latar belakang+tujuan), Isi (data+analisis+temuan), Penutup (kesimpulan+rekomendasi), Lampiran. 60% data, 40% analisis. Heading/sub-heading. Bullet points. Chart/grafik untuk visual.', 'writing'),
('writing_essay', E'Essay & Artikel. Pendahuluan: hook + thesis. Isi: argumen + bukti per paragraf. Penutup: rephrase thesis + closing. Topic sentence + evidence + analysis per paragraf. Transisi antar paragraf. Revision: baca ulang 24 jam. Citation: APA/MLA/Harvard.', 'writing'),
('writing_persuasive', E'Copywriting & Persuasi. AIDA: Attention (judul menarik), Interest (masalah/pain point), Desire (solusi+manfaat), Action (CTA jelas). Tips: "Anda" bukan "Kami". Fokus manfaat bukan fitur. Social proof. Urgency. Simple language. Power words: Gratis, Terbukti, Rahasia.', 'writing'),
('finance', E'Keuangan. Aturan 50/30/20: 50% kebutuhan, 30% keinginan, 20% tabungan. Investasi: Reksadana (modal kecil), Saham (tinggi), Obligasi (stabil), Deposito (aman). Bunga Majemuk: FV=PV*(1+r)^n. Emergency fund 3-6x pengeluaran. Mulai SEKARANG.', 'general'),
('productivity', E'Produktivitas. Pomodoro: 25min fokus + 5min break. 4x lalu 15-30min break. Eisenhower Matrix: Urgent+Important=DO, Important+Not Urgent=SCHEDULE, Urgent+Not Important=DELEGATE, Neither=DELETE. GTD: Capture-Clarify-Organize-Review-Execute. Deep Work: blok 2-4 jam tanpa gangguan.', 'general'),
('web_typing', E'Typing Test. 3 difficulty: Easy/Medium/Hard. 4 waktu: 15s/30s/60s/120s. Solo + Multiplayer. EN + ID. Tips: accuracy 95%+, latihan 15-30min/hari, touch typing 10 jari, jangan lihat keyboard.', 'general'),
